// @vitest-environment jsdom
// The fixtures in ./fixtures are REAL backend output (generated by running the
// experiment code), so these tests check the pages against the true API shapes.
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent, cleanup, within } from '@testing-library/react'
import BatchesPage from '../src/pages/BatchesPage.jsx'
import BatchResults from '../src/pages/BatchResults.jsx'
import ExperimentComparison from '../src/pages/ExperimentComparison.jsx'
import batchResults from './fixtures/batch_results.json'
import batchRunning from './fixtures/batch_running.json'
import expAb from './fixtures/experiment_ab.json'
import expRepeat from './fixtures/experiment_repeat.json'
import expSeq from './fixtures/experiment_sequence.json'
import expMcp from './fixtures/experiment_mcp.json'
import presets from './fixtures/presets.json'

globalThis.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} }

let posts
function mockApi(overrides = {}) {
  posts = []
  globalThis.fetch = vi.fn(async (url, opts = {}) => {
    const u = String(url)
    if (opts.method === 'POST') posts.push({ url: u, body: JSON.parse(opts.body || '{}') })
    const json = (b) => ({ ok: true, json: async () => b })
    for (const [pattern, body] of Object.entries(overrides)) if (u.includes(pattern)) return json(typeof body === 'function' ? body(u, opts) : body)
    if (u.endsWith('/experiments/presets')) return json(presets)
    if (u.includes('/batch?limit')) return json({ batches: [] })
    if (u.includes('/experiments?limit')) return json({ experiments: [] })
    if (u.endsWith('/batch') && opts.method === 'POST') return json({ batch_id: 'b-new', status: 'running', total: 2 })
    if (u.endsWith('/experiments') && opts.method === 'POST') return json({ experiment_id: 'e-new' })
    if (u.includes('/results')) return json(batchResults)
    return json({})
  })
}
beforeEach(() => { cleanup(); mockApi() })

describe('batch results page', () => {
  it('shows progress, KPIs, every project, and exports', async () => {
    mockApi({ '/batch/b1/results': batchResults })
    render(<BatchResults batchId="b1" onBack={() => {}} onOpenProject={() => {}} />)
    await screen.findByText(/finished/)
    const rows = batchResults.rows
    expect(screen.getByRole('progressbar').getAttribute('aria-valuenow')).toBe('100')
    expect(screen.getByText(`${batchResults.summary.passed}/${batchResults.summary.runs}`)).toBeTruthy()
    expect(screen.getByText(`${rows.length} of ${rows.length}`)).toBeTruthy()
    expect(screen.getByText('⬇ CSV').getAttribute('href')).toContain('/batch/b1/results?format=csv')
    expect(screen.queryByText('✕ Cancel')).toBeNull()                       // finished: nothing to cancel
  })

  it('filters by status, text and cost range; sorts by a column; drills down', async () => {
    const onOpen = vi.fn()
    render(<BatchResults batchId="b1" onBack={() => {}} onOpenProject={onOpen} />)
    await screen.findByText(/finished/)
    const n = batchResults.rows.length
    const costs = batchResults.rows.map((r) => r.est_cost_usd).sort((a, b) => a - b)
    const mid = (costs[Math.floor(n / 2)])
    fireEvent.change(screen.getByLabelText('min cost'), { target: { value: String(mid) } })
    const kept = batchResults.rows.filter((r) => r.est_cost_usd >= mid).length
    expect(screen.getByText(`${kept} of ${n}`)).toBeTruthy()
    fireEvent.change(screen.getByLabelText('min cost'), { target: { value: '' } })
    fireEvent.change(screen.getByPlaceholderText('Search request…'), { target: { value: 'fibonacci' } })
    expect(screen.getByText(`${batchResults.rows.filter((r) => r.request.toLowerCase().includes('fibonacci')).length} of ${n}`)).toBeTruthy()
    fireEvent.change(screen.getByPlaceholderText('Search request…'), { target: { value: '' } })
    fireEvent.change(screen.getByLabelText('filter status'), { target: { value: 'passed' } })
    expect(screen.getByText(`${batchResults.rows.filter((r) => r.status === 'passed').length} of ${n}`)).toBeTruthy()
    fireEvent.change(screen.getByLabelText('filter status'), { target: { value: '' } })
    fireEvent.click(screen.getAllByRole('columnheader').find((h) => h.textContent.startsWith('Tokens')))
    const firstCell = screen.getAllByRole('row')[1].textContent
    const top = [...batchResults.rows].sort((a, b) => b.tokens_total - a.tokens_total)[0]
    expect(firstCell).toContain(top.tokens_total.toLocaleString())
    fireEvent.click(screen.getAllByText('Metrics →')[0])
    expect(onOpen).toHaveBeenCalledTimes(1)
    expect(batchResults.rows.map((r) => r.project_id)).toContain(onOpen.mock.calls[0][0])
  })

  it('a running batch shows live progress and a cancel button that posts', async () => {
    mockApi({ '/batch/b2/results': batchRunning, '/batch/b2/cancel': { cancelled: true } })
    render(<BatchResults batchId="b2" onBack={() => {}} onOpenProject={() => {}} />)
    await screen.findByText(/6\/15 finished/)
    expect(screen.getByRole('progressbar').getAttribute('aria-valuenow')).toBe('40')
    fireEvent.click(screen.getByText('✕ Cancel'))
    await waitFor(() => expect(posts.some((p) => p.url.endsWith('/batch/b2/cancel'))).toBe(true))
  })
})

describe('experiment comparison page', () => {
  const open = (res, id = 'e1') => {
    mockApi({ [`/experiments/${id}/results`]: res })
    render(<ExperimentComparison experimentId={id} onBack={() => {}} onOpenBatch={() => {}} />)
  }

  it('A/B: verdict, significance badges, statistics table, exports and the reproducibility block', async () => {
    open(expAb)
    await screen.findByText('Verdict')
    const r = expAb.result
    expect(screen.getByText(r.verdict[0])).toBeTruthy()
    expect(screen.getByText('Read before citing')).toBeTruthy()
    const tok = r.comparisons.tokens_total.comparisons[0]
    expect(tok.significant).toBe(true)
    expect(screen.getAllByText(/✓ significant/).length).toBeGreaterThan(0)
    expect(screen.getByText(`Statistical comparisons vs`, { exact: false })).toBeTruthy()
    const table = screen.getAllByRole('table').find((t) => t.textContent.includes("Cohen's d"))
    expect(within(table).getAllByRole('row').length).toBeGreaterThan(4)       // header + one row per metric/level
    expect(table.textContent).toContain('large')
    expect(screen.getByText('⬇ LaTeX').getAttribute('href')).toContain('/experiments/e1/results?format=latex')
    expect(screen.getByText('⬇ Raw CSV').getAttribute('href')).toContain('format=csv')
    expect(screen.getByText(/Reproducibility/)).toBeTruthy()
    expect(document.querySelector('.repro pre').textContent).toContain('"environment"')
    expect(document.querySelector('.repro pre').textContent).toContain(expAb.experiment.config.environment.default_model)
  })

  it('a running experiment shows progress and no result yet', async () => {
    open({ experiment: { ...expAb.experiment, status: 'running', progress: 0.5, finished_runs: 15 }, result: null })
    await screen.findByText(/Results appear when every condition has finished/)
    expect(screen.getByRole('progressbar').getAttribute('aria-valuenow')).toBe('50')
    expect(screen.queryByText('Verdict')).toBeNull()
    expect(screen.getByText('✕ Cancel')).toBeTruthy()
  })

  it('low-power comparisons are flagged', async () => {
    const lowPower = JSON.parse(JSON.stringify(expAb))
    lowPower.result.comparisons.tokens_total.comparisons[0].low_power = true
    open(lowPower)
    await screen.findByText('Verdict')
    expect(screen.getAllByText(/low n/).length).toBeGreaterThan(0)
  })

  it('repeat, sequence and mcp_overhead designs render their own views', async () => {
    open(expRepeat, 'r1')
    await screen.findByText(/First \(cold\) vs repeat \(warm\)/)
    expect(screen.getByText(/pair\(s\) excluded/)).toBeTruthy()
    cleanup()
    open(expSeq, 's1')
    await screen.findByText('Attempts per task by position')
    expect(screen.getByText('Slope / position')).toBeTruthy()
    cleanup()
    open(expMcp, 'm1')
    await screen.findByText('MCP write_file')
    expect(screen.getByText(/Overhead/)).toBeTruthy()
  })
})

describe('new batch / new experiment forms', () => {
  it('a batch: one request per line, defaults sent, then jumps to its results', async () => {
    mockApi({ '/batch/b-new/results': batchResults })
    render(<BatchesPage onOpenProject={() => {}} />)
    const box = await screen.findByPlaceholderText(/a function that checks/)
    const button = screen.getByRole('button', { name: /Run/ })
    expect(button.disabled).toBe(true)                                         // nothing typed yet
    fireEvent.change(box, { target: { value: 'first request\n\n  second request  \n' } })
    expect(screen.getByRole('button', { name: /Run 2 requests/ })).toBeTruthy()
    fireEvent.change(screen.getByLabelText('framework'), { target: { value: 'flask' } })
    fireEvent.change(screen.getByLabelText('memory'), { target: { value: 'off' } })
    fireEvent.change(screen.getByLabelText('max attempts'), { target: { value: '2' } })
    fireEvent.change(screen.getByLabelText('concurrency'), { target: { value: '3' } })
    fireEvent.click(screen.getByRole('button', { name: /Run 2 requests/ }))
    await waitFor(() => expect(posts.some((p) => p.url.endsWith('/batch'))).toBe(true))
    expect(posts.find((p) => p.url.endsWith('/batch')).body).toEqual({
      requests: ['first request', 'second request'], defaults: { framework: 'flask', max_qa_attempts: 2, use_memory: false }, max_concurrency: 3 })
    await screen.findByText(/finished/)                                         // navigated to the new batch
  })

  it('an experiment: a preset fills the form; levels are parsed per factor', async () => {
    render(<BatchesPage onOpenProject={() => {}} />)
    fireEvent.click(await screen.findByText('Experiments'))
    await waitFor(() => expect(screen.getByLabelText('levels').value).toBe('blackboard, message_passing'))
    expect(screen.getByLabelText('requests').value.split('\n').length).toBe(5)
    expect(screen.getByLabelText('repetitions').value).toBe('3')
    fireEvent.change(screen.getByLabelText('preset'), { target: { value: 'memory' } })
    await waitFor(() => expect(screen.getByLabelText('levels').value).toBe('off, on'))
    fireEvent.change(screen.getByLabelText('preset'), { target: { value: 'retry_policy' } })
    await waitFor(() => expect(screen.getByLabelText('levels').value).toBe('1, 3, 5'))
    fireEvent.change(screen.getByLabelText('levels'), { target: { value: '2, 4' } })
    mockApi({ '/experiments/e-new/results': expAb })
    fireEvent.click(screen.getByRole('button', { name: /Run experiment/ }))
    await waitFor(() => expect(posts.some((p) => p.url.endsWith('/experiments'))).toBe(true))
    const body = posts.find((p) => p.url.endsWith('/experiments')).body
    expect(body).toMatchObject({ preset: 'retry_policy', design: 'ab', factor: 'max_qa_attempts', levels: [2, 4], repetitions: 3 })
    expect(body.requests.length).toBe(5)
    await screen.findByText('Verdict')

    cleanup()
    render(<BatchesPage onOpenProject={() => {}} />)
    fireEvent.click(await screen.findByText('Experiments'))
    fireEvent.change(await screen.findByLabelText('preset'), { target: { value: 'memory' } })
    await waitFor(() => expect(screen.getByLabelText('levels').value).toBe('off, on'))
    mockApi({ '/experiments/e-new/results': expAb })
    fireEvent.click(screen.getByRole('button', { name: /Run experiment/ }))
    await waitFor(() => expect(posts.length).toBe(1))
    expect(posts[0].body.levels).toEqual([false, true])                         // use_memory levels become booleans
  })

  it('an error from the backend is shown, not swallowed', async () => {
    mockApi({ '/experiments': () => { throw new Error('x') } })
    globalThis.fetch = vi.fn(async (url, opts = {}) => {
      if (opts.method === 'POST') return { ok: false, status: 422, json: async () => ({ detail: 'levels must list at least two values of the factor' }) }
      return { ok: true, json: async () => (String(url).includes('presets') ? presets : { batches: [], experiments: [] }) }
    })
    render(<BatchesPage onOpenProject={() => {}} />)
    fireEvent.click(await screen.findByText('Experiments'))
    await waitFor(() => expect(screen.getByLabelText('levels').value).not.toBe(''))
    fireEvent.click(screen.getByRole('button', { name: /Run experiment/ }))
    await screen.findByText(/levels must list at least two values/)
  })
})
